public struct CardState {
    public var reps: Int32
    public var lapses: Int32
    public var intervalDays: Double
    public var due: Int64
    public var last: Int64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(reps: Int32, lapses: Int32, intervalDays: Double, due: Int64, last: Int64) {
        self.reps = reps
        self.lapses = lapses
        self.intervalDays = intervalDays
        self.due = due
        self.last = last
    }
}

#if compiler(>=6)
extension CardState: Sendable {}
#endif


extension CardState: Equatable, Hashable {
    public static func ==(lhs: CardState, rhs: CardState) -> Bool {
        if lhs.reps != rhs.reps {
            return false
        }
        if lhs.lapses != rhs.lapses {
            return false
        }
        if lhs.intervalDays != rhs.intervalDays {
            return false
        }
        if lhs.due != rhs.due {
            return false
        }
        if lhs.last != rhs.last {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(reps)
        hasher.combine(lapses)
        hasher.combine(intervalDays)
        hasher.combine(due)
        hasher.combine(last)
    }
}



