public enum Access {
    
    case checking
    case locked
    case trial(productId: String, untilMs: Int64?
    )
    case subscribed(productId: String, untilMs: Int64?
    )
    case beta
}


#if compiler(>=6)
extension Access: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAccess: FfiConverterRustBuffer {
    typealias SwiftType = Access

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Access {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .checking
        
        case 2: return .locked
        
        case 3: return .trial(productId: try FfiConverterString.read(from: &buf), untilMs: try FfiConverterOptionInt64.read(from: &buf)
        )
        
        case 4: return .subscribed(productId: try FfiConverterString.read(from: &buf), untilMs: try FfiConverterOptionInt64.read(from: &buf)
        )
        
        case 5: return .beta
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Access, into buf: inout [UInt8]) {
        switch value {
        
        
        case .checking:
            writeInt(&buf, Int32(1))
        
        
        case .locked:
            writeInt(&buf, Int32(2))
        
        
        case let .trial(productId,untilMs):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(productId, into: &buf)
            FfiConverterOptionInt64.write(untilMs, into: &buf)
            
        
        case let .subscribed(productId,untilMs):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(productId, into: &buf)
            FfiConverterOptionInt64.write(untilMs, into: &buf)
            
        
        case .beta:
            writeInt(&buf, Int32(5))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAccess_lift(_ buf: RustBuffer) throws -> Access {
    return try FfiConverterTypeAccess.lift(buf)
}

